class code_block_controller_default extends Controller {
  static targets = ["source"];
  static values = { copiedLabel: String };
  async copy(event) {
    event.preventDefault();
    const text = this.sourceTarget.innerText;
    try {
      await navigator.clipboard.writeText(text);
    } catch {
      const ta = document.createElement("textarea");
      ta.value = text;
      document.body.appendChild(ta);
      ta.select();
      document.execCommand("copy");
      ta.remove();
    }
    this.flash(event.currentTarget);
  }
  flash(button) {
    const label = button.querySelector(".code-block__copy-label");
    if (!label)
      return;
    const original = label.textContent;
    label.textContent = this.copiedLabelValue || original;
    setTimeout(() => {
      label.textContent = original;
    }, 1200);
  }
}

